code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    paths = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == 1:
                path = [(r, c+1), (r, c+2), (r-1, c+2)]
            elif v == 2:
                path = [(r, c-k) for k in range(1, 5)]
            elif v == 3:
                path = [(r+k, c) for k in range(1, 4)]
            elif v == 6:
                path = [(r-k, c) for k in range(1, 7)]
            else:
                continue
            path = [(rr, cc) for rr, cc in path if 0 <= rr < h and 0 <= cc < w]
            paths.append((v, (r, c), path))
    seen = {}
    collisions = set()
    for v, start, path in paths:
        for i, pos in enumerate(path):
            if pos in seen:
                collisions.add(pos)
            else:
                seen[pos] = (v if i == len(path)-1 else 5)
    for v, start, path in paths:
        if 0 <= start[0] < h and 0 <= start[1] < w:
            out[start[0]][start[1]] = v
        for i, (r, c) in enumerate(path):
            if (r, c) not in collisions:
                out[r][c] = v if i == len(path)-1 else 5
    for r, c in collisions:
        out[r][c] = 4
    for r, c in collisions:
        rr, cc = r+1, c-1
        while 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
'''
